import { describe, expect, it } from 'vitest';
import { createGrid, withLetter, type Coord, type Grid } from '../engine/grid';
import { clearOutsideLockedWords, type LockedWord } from './locked-words';

// Story 21-S6 — Reset Grid's Keep Locked Words. Every cell outside a
// locked word becomes white and empty, black cells included; each locked
// word's cells keep exactly what they hold (a rebus too). The lock list
// isn't the function's business: the caller keeps it unchanged. The input
// grid is not changed.
//
// Do not edit this file to match an implementation.

/** A grid from rows of text: a letter is a lettered cell, '.' an empty
 *  one, '#' a black one. `rebus` puts a multi-letter entry at a cell. */
function gridOf(rows: string[], rebus: { at: Coord; value: string }[] = []): Grid {
  const black: Coord[] = [];
  rows.forEach((letters, row) =>
    [...letters].forEach((letter, col) => {
      if (letter === '#') black.push({ col, row });
    })
  );
  let grid = createGrid({ cols: rows[0].length, rows: rows.length, black });
  rows.forEach((letters, row) => {
    [...letters].forEach((letter, col) => {
      if (letter !== '.' && letter !== '#') grid = withLetter(grid, { col, row }, letter);
    });
  });
  for (const { at, value } of rebus) grid = withLetter(grid, at, value);
  return grid;
}

//   # C A T # .     row 0: CAT, locked across, black on both ends
//   . . O . . .     column 2: AON, locked down, sharing CAT's A
//   . H N . . .     row 2: H is outside every locked word
//   . . . . A T     row 3: AT, not locked
//   . D O G S #     row 4: DOGS, not locked
const BEFORE = gridOf(['#CAT#.', '..O...', '.HN...', '....AT', '.DOGS#']);

const CAT: LockedWord = { col: 1, row: 0, orientation: 'across', length: 3 };
const AON: LockedWord = { col: 2, row: 0, orientation: 'down', length: 3 };

describe('21-S6-1 Keep Locked Words', () => {
  it('leaves exactly the locked words\' letters; every other cell white and empty', () => {
    const after = clearOutsideLockedWords(BEFORE, [CAT, AON]);
    expect(after).toEqual(gridOf(['.CAT..', '..O...', '..N...', '......', '......']));
  });

  it('keeps a locked word\'s rebus as it is', () => {
    const before = gridOf(['#C.T#.', '......'], [{ at: { col: 2, row: 0 }, value: 'OW' }]);
    const after = clearOutsideLockedWords(before, [CAT]);
    expect(after).toEqual(gridOf(['.C.T..', '......'], [{ at: { col: 2, row: 0 }, value: 'OW' }]));
  });

  it('with no locked words, clears every cell, black ones included', () => {
    expect(clearOutsideLockedWords(BEFORE, [])).toEqual(createGrid({ cols: 6, rows: 5 }));
  });

  it('does not change the grid it is given', () => {
    const copy = gridOf(['#CAT#.', '..O...', '.HN...', '....AT', '.DOGS#']);
    clearOutsideLockedWords(BEFORE, [CAT]);
    expect(BEFORE).toEqual(copy);
  });
});
